 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        const vCurDate = $c.ut.cGetToday("yyyymmdd");
        edt_ConfirmDate.setValue(vCurDate);

        //    buttonSet.setDsclInfo( btn_Dscl, fn_dscl );            // 안내문작성

        await scwin.setCode();
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41313.onpageload" });
    }
};

