/**
 * @method
 * @name checkEtnList
 * @description ETN 종목 대상 확인
 * @param {*} dtsObj dtsObj
 * @param {*} procJob procJob
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkEtnList = async function(dtsObj, procJob) {
    // 상장원부 상장대상 조회
    const sbmOptions = {
        id : "sbm_dts_Etn",
        action : "/etn/EtnCodeAct.do",
        ref : "",
        target : "dts_Etn=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    if (dtsObj.getRowCount() === dts_Etn.getRowCount()) {
        for (let i = 1; i <= dtsObj.getRowCount(); i++) {
            IsuCd = dtsObj.getCellData(i, "ISU_CD");
            bChecked = false;
            for (let j = 1; j <= dts_Etn.getRowCount(); j++) {
                if (IsuCd === dts_Etn.getCellData(j, "ISU_CD")) {
                    bChecked = true;
                    break;
                }
            }
            if (bChecked === false) {
                return IsuCd + " " + dtsObj.getCellData(i, "ISU_KOR_ABBRV") + "종목은 ETN상장원부 상장된 종목 아닙니다.";
            }
        }
    } else {
        let errMsg = "";
        errMsg = "LP보유량 마감종목 대상(" + dtsObj.getRowCount() + ")이 전체 마감대상(" + dts_Etn.getRowCount() + ") 종목수와 다릅니다.\n";
        if (cmb_ISUR_CD.getValue() !== '') {
            errMsg = errMsg + "\n검색조건 '발행회사명'을 '전체'로 하여 " + procJob + " 버튼을 선택하시길 바랍니다.";
        }
        return errMsg;
    }
    return "";
};

/**
 * @method
 * @name selectCloseError
 * @description select Close Error 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.selectCloseError = async function() {
    const sbmOptions = {
        id : "sbm_dts_closeStatus",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_closeStatus=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    if (dts_closeStatus.getRowCount() > 0) {
        if (dts_closeStatus.getCellData(1, 'CD_ID') === '15' && dts_closeStatus.getCellData(1, 'VALUE') === 'Y') {
            return "N";
        } else if (dts_closeStatus.getCellData(1, 'CD_ID') === '15' && dts_closeStatus.getCellData(1, 'VALUE') === 'N') {
            await $c.win.alert("ETN 법인제출 마감이 되지 않아 마감처리 불가능합니다.");
            return "Y";
        } else {
            await $c.win.alert("ETN 법인제출 마감확인이 되지 않습니다.\n시스템 관리자에게 문의 하시기 바랍니다.");
            return "Y";
        }
    } else {
        await $c.win.alert("ETN 법인제출 마감확인이 되지 않습니다.\n시스템 관리자에게 문의 하시기 바랍니다.");
        return "Y";
    }
};

/**
 * @method
 * @name trsRevw
 * @description 담당자 확인
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trsRevw = async function() {
    // transaction을 위한 세팅
    dts_List.setBroadcast(false);
    for (let i = 1; i <= dts_List.getRowCount(); i++) {
        dts_List.setCellData(i, "CHECK", "T");
    }
    dts_List.setBroadcast(true, true);
    // alert(dts_Process.CountRow);
    trs_revw.KeyName = "toinb_dataid4";
    const sbmOptions = {
        id : "sbm_trs_revw",
        action : "/etn/EtnLpMgt.do",
        ref : "dts_List",
        target : "trs_revw=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

