/**
 * @method
 * @name dateErrCheck
 * @description date Err Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dateErrCheck = async function() {
    if (edt_ConfirmDate.getValue() === "" || edt_ConfirmDate.Text.length < 8) {
        await $c.win.alert("마감일을 입력하세요.");
        edt_ConfirmDate.focus();
        return true;
    }
};

/**
 * @method
 * @name excelDown
 * @description 정보를 excel로 다운 받는다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excelDown = async function() {
    if (dts_List.getRowCount() > 0) {
        $c.stf.doLogSave("ULDSTF41313.xml", SCREN_PROCS_TP_CD_01);
        $c.data.downloadGridViewExcel(grd_List, {fileName: "ETN LP보유량 마감", type: "3"});
    } else {
        await $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};

/**
 * @method
 * @name selectExtractError
 * @description 목록 중 추출실패건 유무 확인
 * @param {*} dtsObj dtsObj
 * @returns {void}
 * @hidden N
 */
scwin.selectExtractError = function(dtsObj) {
    for (let i = 1; i <= dtsObj.getRowCount(); i++) {
        const acptNo = dtsObj.getCellData(i, "ACPT_NO");
        const offQty = dtsObj.getCellData(i, "OFFHR_DISCLS_INCDEC_QTY");
        if ("" !== acptNo && "0" === offQty) {
            // 공시는 제출됬으나 추출값이 없는 케이스
            return dtsObj.getCellData(i, "ISU_KOR_ABBRV");
        }
    }
    return "";
};

/**
 * @method
 * @name selectQtyError
 * @description 목록 중 상장수량보다 합계수량이 큰 경우 담당자 확인이 불가능하도록 한다.
 * @param {*} dtsObj dtsObj
 * @returns {void}
 * @hidden N
 */
scwin.selectQtyError = function(dtsObj) {
    for (let i = 1; i <= dtsObj.getRowCount(); i++) {
        const isuQty = dtsObj.getCellData(i, "ETN_ISU_QTY");
        const totalQty = dtsObj.getCellData(i, "TOTAL_QTY");
        if (parseInt(isuQty) < parseInt(totalQty)) {
            // 상장수량보다 합계수량이 큰 경우
            // alert(parseInt(isuQty) + "," + parseInt(totalQty));
            return dtsObj.getCellData(i, "ISU_KOR_ABBRV");
        }
    }
    return "";
};

/**
 * @method
 * @name isFinalDataReady
 * @description 시장정보 및 시장감시 데이터 확인
 * @param {*} dtsObj dtsObj
 * @returns {void}
 * @hidden N
 */
scwin.isFinalDataReady = function(dtsObj) {
    for (let i = 1; i <= dtsObj.getRowCount(); i++) {
        const mktQty = dtsObj.getCellData(i, "REGULSS_MKT_HD_QTY");
        const bidQty = dtsObj.getCellData(i, "TDD_BID_QTY");
        const askQty = dtsObj.getCellData(i, "TDD_ASK_QTY");
        if (-1 === mktQty || -1 === bidQty || -1 === askQty) {
            // 시정, 시감 데이터가 하나라도 없는 경우
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name revw
 * @description 담당자 확인 버튼 클릭시
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.revw = async function() {
    procJob = "담당자 확인";
    let errMsg = await scwin.checkEtnList(dts_List, procJob); // by lds323
    if ('' !== errMsg) {
        await $c.win.alert(errMsg);
        return false;
    }
    const wrongIsuCd = scwin.selectExtractError(dts_List);
    const wrongQtyCd = scwin.selectQtyError(dts_List);
    const wrongClose = await scwin.selectCloseError();

    // alert(wrongIsuCd);
    if ("Y" === wrongClose) {
        return false;
    } else if ('' !== wrongIsuCd) {
        await $c.win.alert("마감 대상종목 중 정규시장 외 취득/처분 보고 추출실패건이 포함되어 있습니다. \n정규시장외 공시증감수량내역을 확인하세요. \n 해당종목 : " + wrongIsuCd);
        return false;
    } else if ('' !== wrongQtyCd) {
        await $c.win.alert("마감 대상종목 중 상장수량보다 합계수량이 큰 건이 포함되어 있습니다. 합계수량을 확인하세요. \n 해당종목 : " + wrongQtyCd);
        return false;
    } else {
        let res = window.confirm(procJob + " 마감처리 하시겠습니까?");
        if (res) {
            await scwin.trsRevw();
        }
    }
};

/**
 * @method
 * @name aprv
 * @description 팀장승인 버튼 클릭시
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.aprv = async function() {
    procJob = "팀장승인";
    if (txb_CONFRM_DDTM.getValue() === "") {
        await $c.win.alert("담당자확인 완료 후 승인처리 가능합니다.");
        return false;
    } else {
        let errMsg = await scwin.checkEtnList(dts_List, procJob); // by lds323
        if ('' !== errMsg) {
            await $c.win.alert(errMsg);
            return false;
        }
        let res = window.confirm(procJob + " 마감처리 하시겠습니까?");
        if (res) {
            await scwin.trsAprv();
        }
    }
};

