/**
 * @method
 * @name dscl
 * @description 안내문 작성  - 당일 전부보유목록
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dscl = async function() {
    let vBzProcsNo = "";

    // 2010.07.23 업무처리번호 유무 - 정정공시를 위해
    await scwin.getBzProcsNo();
    vBzProcsNo = dts_BzProcsNo.getCellData(1, "BZ_PROCS_NO");
    if (vBzProcsNo === "") vBzProcsNo = await $c.stf.getNewBzProcNo(dts_BzProcsNo);
    if (vBzProcsNo.length !== 14) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        return;
    }
    if (cmb_ISUR_CD.getValue() !== "") {
        await $c.win.alert("안내문작성을 위해 발행회사를 전체로 하여 다시 조회합니다");
        cmb_ISUR_CD.setValue("");
        await scwin.listSync();
    }
    const OldGet = scwin.getPar;
    const OldSet = scwin.setPar;
    scwin.getPar = function(arr, param_dts_List, param_dts_NOW_DD) {
        arr[0] = "68377";
        arr[1] = vBzProcsNo;
        arr[2] = '99999'; // 거래소코드
        arr[3] = '1'; // 시장구분

        // dts_NOW_DD.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
        dts_NOW_DD.insertRow();
        dts_NOW_DD.setCellData(1, "TASK_DD", edt_ConfirmDate.getValue());
        $c.stf.copyDataSet(dts_List, param_dts_List);
        $c.stf.copyDataSet(dts_NOW_DD, param_dts_NOW_DD);
        return arr.length;
    };
    scwin.setPar = function(arr) {

    };
    const wth = 730 + 5;
    const hgt = 785 + 30;
    const pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    const options = {
        id: "ULDSTF92024",
        title: "공시안내문작성",
        type: "browserPopup",
        width: wth,
        height: hgt,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/listingcommon/ULDSTF92024.gfm", options);
    scwin.getPar = OldGet;
    scwin.setPar = OldSet;
};

